CREATE TABLE IF NOT EXISTS "AiUsage" ("id" TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,"userId" TEXT NOT NULL,"planCode" TEXT NOT NULL,"operation" TEXT NOT NULL,"credits" INTEGER NOT NULL CHECK ("credits">0),"provider" TEXT NOT NULL,"model" TEXT,"requestHash" TEXT NOT NULL,"latencyMs" INTEGER,"success" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),CONSTRAINT "AiUsage_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE); CREATE INDEX IF NOT EXISTS "AiUsage_userId_createdAt_idx" ON "AiUsage"("userId","createdAt"); CREATE INDEX IF NOT EXISTS "AiUsage_operation_createdAt_idx" ON "AiUsage"("operation","createdAt"); ALTER TABLE "AiUsage" ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "AiUsage service role" ON "AiUsage"; CREATE POLICY "AiUsage service role" ON "AiUsage" FOR ALL USING (auth.role()='service_role') WITH CHECK (auth.role()='service_role');
